from pathlib import Path
import base64,zlib,json,hashlib,shutil,datetime,subprocess,sys,tempfile,sqlite3
v=json.loads(zlib.decompress(base64.b64decode('')))
root=Path('/opt/kiwoom/current');page=Path('/opt/kiwoom/dashboard-source/dist/index.html');html=page.read_text()
for n,h in v['hashes'].items():assert hashlib.sha256((root/n).read_bytes()).hexdigest()==h,n+' changed'
newhtml=html
for ident,u in v['ui'].items():
 tag='<script id="'+ident+'">';a=newhtml.index(tag)+len(tag);b=newhtml.index('</script>',a)
 assert hashlib.sha256(newhtml[a:b].strip().encode()).hexdigest()==v['uihash'][ident],ident+' changed'
 newhtml=newhtml[:a]+'\n'+u.strip()+'\n'+newhtml[b:]
with tempfile.TemporaryDirectory(prefix='quantity-check-') as tmp:
 stage=Path(tmp)
 for src in root.glob('*.py'):shutil.copy2(src,stage/src.name)
 for n,s in {**v['files'],**v['tests']}.items():(stage/n).write_text(s)
 subprocess.run([sys.executable,'-W','ignore::ResourceWarning','-m','unittest','test_quantity_rule','test_auto_performance','test_auto_performance_history','test_signal_validation','test_signal_period','test_signal_history'],cwd=stage,check=True)
sys.path.insert(0,str(root))
from trading_control import locked
services=['moa-auto-trading','moa-signal-validation','moa-real-performance','kiwoom-refresh']
for unit in services:subprocess.run(['systemctl','is-active','--quiet',unit],check=True)
suffix='.before-five-share-'+datetime.datetime.now().strftime('%Y%m%d%H%M%S')
changes={root/n:s for n,s in v['files'].items()};changes[page]=newhtml
with locked(Path('/opt/kiwoom/state/trading-control.sqlite3')):
 subprocess.run(['systemctl','stop',*services],check=True)
 try:
  dbpath=Path('/opt/kiwoom/state/auto-trading.sqlite3')
  with sqlite3.connect(dbpath) as db,sqlite3.connect(str(dbpath)+suffix) as backup:
   db.backup(backup);before=db.execute('SELECT market,strategy,enabled,revision,budget,started FROM portfolios ORDER BY market').fetchall()
  for p,s in changes.items():
   shutil.copy2(p,str(p)+suffix);temp=p.with_name(p.name+'.quantity-new');temp.write_text(s);temp.chmod(p.stat().st_mode);shutil.chown(temp,user=p.stat().st_uid,group=p.stat().st_gid);temp.replace(p)
  with sqlite3.connect(dbpath) as db:assert before==db.execute('SELECT market,strategy,enabled,revision,budget,started FROM portfolios ORDER BY market').fetchall()
 except Exception:
  for p in changes:
   backup=Path(str(p)+suffix)
   if backup.exists():shutil.copy2(backup,p)
  raise
 finally:
  subprocess.run(['systemctl','start',*services],check=True)
subprocess.run(['systemctl','is-active',*services],check=True)
print('FIVE_SHARE_DEPLOYED',suffix,'SETTINGS_PRESERVED')
